We could change:

```
       if ((err = gcry_cipher_open(&cipher_hd, algo, mode, 0))) {
                DEBUG("GCRY: open %s/%s", gcry_strsource(err), gcry_strerror(err));
                return FALSE;
       }
```
into
```
       err = gcry_cipher_open(&cipher_hd, algo, mode, 0);
       if (err != GPG_ERR_NO_ERROR) {
                DEBUG("GCRY: open %s/%s", gcry_strsource(err), gcry_strerror(err));
                return FALSE;
       }
